#include <list>
#include <iostream>
#include <stdexcept>

typedef int ItemType;

class Stack
{
 public:
  Stack();
  bool pop();
  ItemType top();
  void push(const ItemType& val);
  int size() { return list_.size(); }
 private:
  std::list<ItemType> list_;
};

Stack::Stack()
{
}

bool Stack::pop()
{
  if (list_.size() == 0)
    return false;

  list_.pop_front();
  return true;
}

ItemType Stack::top()
{
  if (list_.size() == 0)
    throw std::runtime_error("Trying to access empty stack");

  return list_.front();
}

void Stack::push(const ItemType& val)
{
  list_.push_front(val);
}

int main()
{
  Stack s;
  s.push(5);
  s.push(6);
  s.push(7);
  try
  {
    std::cout << s.top() << std::endl;
    s.pop();
    std::cout << s.top() << std::endl;
    s.pop();
    std::cout << s.top() << std::endl;
    s.pop();
  }
  catch (std::runtime_error e)
  {
    std::cout << e.what() << std::endl;
  }
}

